-- ---------- supabase/migrations/20260101000003_functions_triggers.sql ----------
-- Narix Academy — functions and triggers

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------

create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  for t in select unnest(array[
    'profiles','service_categories','services','academic_levels','deadline_options',
    'word_count_options','languages','citation_styles','additional_services','pricing_rules',
    'order_statuses','orders','order_requests','discounts','pages','faqs','samples','testimonials',
    'referral_benefits'
  ])
  loop
    execute format('create trigger set_updated_at before update on %I for each row execute function set_updated_at()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- Role / ownership helpers used throughout RLS policies
-- ---------------------------------------------------------------------------

create or replace function is_admin()
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from profiles where id = auth.uid() and role = 'admin'
  );
$$;

create or replace function owns_order(target_order_id uuid)
returns boolean
language sql
security definer
stable
set search_path = public
as $$
  select exists (
    select 1 from orders where id = target_order_id and user_id = auth.uid()
  );
$$;

-- ---------------------------------------------------------------------------
-- New auth user -> profile row + personal referral code
-- ---------------------------------------------------------------------------

create or replace function generate_referral_code()
returns text
language plpgsql
as $$
declare
  candidate text;
begin
  loop
    candidate := 'NARIX-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    if not exists (select 1 from referral_codes where code = candidate) then
      return candidate;
    end if;
  end loop;
end;
$$;

create or replace function handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  new_code text;
begin
  insert into profiles (id, full_name, email_verified, role, referral_code)
  values (
    new.id,
    new.raw_user_meta_data ->> 'full_name',
    new.email_confirmed_at is not null,
    'user',
    null
  );

  new_code := generate_referral_code();

  insert into referral_codes (code, owner_user_id, max_total_uses)
  values (new_code, new.id, 3);

  update profiles set referral_code = new_code where id = new.id;

  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_auth_user();

create or replace function handle_auth_user_email_verified()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.email_confirmed_at is not null and old.email_confirmed_at is null then
    update profiles set email_verified = true where id = new.id;
  end if;
  return new;
end;
$$;

create trigger on_auth_user_verified
  after update on auth.users
  for each row execute function handle_auth_user_email_verified();

-- ---------------------------------------------------------------------------
-- Order numbering — sequence-backed, race-safe under concurrent submissions
-- ---------------------------------------------------------------------------

create or replace function next_order_number()
returns text
language plpgsql
as $$
declare
  n bigint;
begin
  n := nextval('order_number_seq');
  return 'NA-' || to_char(now(), 'YYYY') || '-' || lpad(n::text, 6, '0');
end;
$$;

-- ---------------------------------------------------------------------------
-- Payment ledger: orders.paid_amount is always derived from the payments
-- ledger, never written directly by the app, so it cannot drift or be
-- double-counted under concurrent inserts.
-- ---------------------------------------------------------------------------

create or replace function recompute_order_paid_amount()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  target_order uuid;
  total numeric(10,2);
begin
  target_order := coalesce(new.order_id, old.order_id);
  select coalesce(sum(amount), 0) into total from payments where order_id = target_order;
  update orders set paid_amount = total, updated_at = now() where id = target_order;
  return null;
end;
$$;

create trigger payments_recompute_paid_amount
  after insert or update or delete on payments
  for each row execute function recompute_order_paid_amount();

-- ---------------------------------------------------------------------------
-- Atomic, race-safe usage counters for promo codes and referral codes.
-- Each returns true only if the increment actually happened (i.e. the code
-- was still under its limit at the moment of the update) — callers must
-- treat a false return as "code exhausted", not retry.
-- ---------------------------------------------------------------------------

create or replace function try_consume_promo_code(p_code_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  updated boolean;
begin
  update promo_codes
     set current_uses = current_uses + 1
   where id = p_code_id
     and active = true
     and current_uses < max_total_uses
     and (expires_at is null or expires_at > now())
  returning true into updated;

  return coalesce(updated, false);
end;
$$;

create or replace function try_consume_referral_code(p_code_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  updated boolean;
begin
  update referral_codes
     set current_uses = current_uses + 1
   where id = p_code_id
     and active = true
     and current_uses < max_total_uses
     and (expires_at is null or expires_at > now())
  returning true into updated;

  return coalesce(updated, false);
end;
$$;

-- ---------------------------------------------------------------------------
-- Generic config-table audit trigger (Admin Pricing Audit requirement)
-- ---------------------------------------------------------------------------

create or replace function log_config_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into audit_logs (actor_id, action, entity_type, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op),
    tg_table_name,
    coalesce(new.id::text, old.id::text),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('UPDATE','INSERT') then to_jsonb(new) else null end
  );
  return coalesce(new, old);
end;
$$;

do $$
declare
  t text;
begin
  for t in select unnest(array[
    'services','service_categories','academic_levels','deadline_options','word_count_options',
    'languages','citation_styles','additional_services','pricing_rules','order_statuses',
    'discounts','promo_codes','referral_codes','email_templates'
  ])
  loop
    execute format(
      'create trigger audit_%I after insert or update or delete on %I for each row execute function log_config_change()',
      t, t
    );
  end loop;
end $$;

-- site_settings keys on `key`, not `id`, so it gets its own audit trigger
create or replace function log_site_settings_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into audit_logs (actor_id, action, entity_type, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op),
    'site_settings',
    coalesce(new.key, old.key),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('UPDATE','INSERT') then to_jsonb(new) else null end
  );
  return coalesce(new, old);
end;
$$;

create trigger audit_site_settings
  after insert or update or delete on site_settings
  for each row execute function log_site_settings_change();

-- ---------- supabase/migrations/20260101000004_rls.sql ----------
-- Narix Academy — Row Level Security
--
-- Design note: tables that require multi-step, transactionally-consistent
-- writes (orders, referral redemption, discount evaluation, payments ledger)
-- are NOT written to directly by client roles. Those writes go through
-- SECURITY DEFINER Postgres functions (see 20260101000005_mutations.sql),
-- which run as the function owner (postgres) and therefore bypass RLS by
-- design — RLS below still fully governs all direct SELECT access and
-- blocks any other write path.

alter table profiles enable row level security;
alter table site_settings enable row level security;
alter table service_categories enable row level security;
alter table services enable row level security;
alter table academic_levels enable row level security;
alter table deadline_options enable row level security;
alter table word_count_options enable row level security;
alter table languages enable row level security;
alter table citation_styles enable row level security;
alter table additional_services enable row level security;
alter table pricing_rules enable row level security;
alter table order_statuses enable row level security;
alter table orders enable row level security;
alter table order_pricing_snapshots enable row level security;
alter table order_additional_services enable row level security;
alter table order_status_history enable row level security;
alter table order_requests enable row level security;
alter table files enable row level security;
alter table messages enable row level security;
alter table payment_requests enable row level security;
alter table payments enable row level security;
alter table notifications enable row level security;
alter table email_templates enable row level security;
alter table notification_jobs enable row level security;
alter table discounts enable row level security;
alter table promo_codes enable row level security;
alter table referral_codes enable row level security;
alter table referrals enable row level security;
alter table referral_benefits enable row level security;
alter table discount_applications enable row level security;
alter table faqs enable row level security;
alter table samples enable row level security;
alter table testimonials enable row level security;
alter table pages enable row level security;
alter table audit_logs enable row level security;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------

create policy profiles_select_own_or_admin on profiles
  for select using (id = auth.uid() or is_admin());

create policy profiles_update_own_or_admin on profiles
  for update using (id = auth.uid() or is_admin())
  with check (id = auth.uid() or is_admin());

-- Role escalation guard: a non-admin may update their own profile row, but
-- never their own role. Enforced with a trigger rather than an RLS subquery
-- because "compare new.role to the pre-update value" is not expressible in
-- a `with check` clause without re-reading the row being written.
create or replace function prevent_self_role_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- auth.uid() is null when the write comes from the service role (direct
  -- SQL, an admin script, bootstrapping the first admin) rather than
  -- through PostgREST as a specific end user — that context is already
  -- privileged by having the service key at all, so only block the change
  -- when it's an authenticated-but-non-admin end user editing their own row.
  if new.role <> old.role and auth.uid() is not null and not is_admin() then
    new.role := old.role;
  end if;
  return new;
end;
$$;

create trigger profiles_prevent_role_escalation
  before update on profiles
  for each row execute function prevent_self_role_escalation();

