-- Admin requests additional info from the client -> notify + email
-- ---------------------------------------------------------------------------

create or replace function notify_order_request_created()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  o orders;
begin
  select * into o from orders where id = new.order_id;

  if o.user_id is not null then
    perform enqueue_notification(
      o.user_id, 'document_requested',
      new.title,
      new.description,
      o.id
    );
  end if;

  perform enqueue_email_job(
    'document_requested', 'document_requested:' || new.id::text,
    'document_requested',
    o.user_id, coalesce(profile_email(o.user_id), o.guest_email),
    jsonb_build_object('order_number', o.order_number, 'title', new.title, 'description', new.description)
  );
  return new;
end;
$$;

create trigger order_requests_notify
  after insert on order_requests
  for each row execute function notify_order_request_created();

-- ---------------------------------------------------------------------------
-- New message -> notify the other party (admin messages notify the client;
-- client messages are surfaced to admins via the unread count in the admin
-- dashboard directly, no per-admin fan-out).
-- ---------------------------------------------------------------------------

create or replace function notify_new_message()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  o orders;
begin
  if new.sender_is_admin then
    select * into o from orders where id = new.order_id;
    if o.user_id is not null then
      perform enqueue_notification(
        o.user_id, 'new_message', 'New message on ' || o.order_number,
        left(coalesce(new.body, 'New attachment'), 140), o.id
      );
      perform enqueue_email_job(
        'new_message', 'new_message:' || new.id::text, 'new_message',
        o.user_id, profile_email(o.user_id),
        jsonb_build_object('order_number', o.order_number)
      );
    end if;
  end if;
  return new;
end;
$$;

create trigger messages_notify
  after insert on messages
  for each row execute function notify_new_message();

-- ---------- supabase/migrations/20260101000006_pricing_engine.sql ----------
-- Narix Academy — pricing + discount engine
--
-- calculate_price() is PURE and READ-ONLY: it writes nothing, ever. It is
-- safe to call on every calculator keystroke (the app debounces/rate-limits
-- calls at the edge regardless — see src/lib/pricing/preview-client.ts).
-- create_order() calls this same function once, server-side, at submission,
-- and is the only place discount candidates get persisted.

create or replace function calculate_price(
  p_service_id uuid,
  p_academic_level_id uuid,
  p_deadline_option_id uuid,
  p_word_count int,
  p_page_count numeric,
  p_language_id uuid,
  p_citation_style_id uuid,
  p_additional_service_ids uuid[],
  p_user_id uuid,
  p_promo_code text,
  p_referral_benefit_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rule pricing_rules;
  deadline deadline_options;
  lang languages;
  citation citation_styles;
  addon additional_services;
  addon_id uuid;
  base numeric(10,2);
  addons_total numeric(10,2) := 0;
  addons_breakdown jsonb := '[]'::jsonb;
  subtotal numeric(10,2);
  candidates jsonb := '[]'::jsonb;
  best jsonb := null;
  cand jsonb;
  member_pct numeric(5,2);
  early discounts;
  promo promo_codes;
  promo_discount discounts;
  benefit referral_benefits;
  is_verified boolean;
begin
  -- calculate_price() trusts p_user_id as given — it is an internal engine
  -- called by create_order() and reevaluate_order_discount(), which have
  -- already resolved the correct target user themselves (auth.uid() for the
  -- former, the order's own owner for the latter — these are not always the
  -- same principal, e.g. an admin re-evaluating someone else's order). It is
  -- NOT a public RPC; see preview_price() below for the client-facing,
  -- self-only entry point, and the REVOKE/GRANT block in 000008.
  select * into rule from pricing_rules
   where service_id = p_service_id and academic_level_id = p_academic_level_id and is_active = true;
  if rule is null then
    raise exception 'NO_PRICING_RULE' using errcode = 'P0001';
  end if;

  select * into deadline from deadline_options where id = p_deadline_option_id and is_active = true;
  if deadline is null then
    raise exception 'INVALID_DEADLINE' using errcode = 'P0001';
  end if;

  base := rule.base_price
        + coalesce(rule.price_per_page, 0) * coalesce(p_page_count, 0)
        + coalesce(rule.price_per_word, 0) * coalesce(p_word_count, 0);

  base := base * deadline.multiplier + deadline.fixed_fee;

  if p_language_id is not null then
    select * into lang from languages where id = p_language_id and is_active = true;
    if lang is not null then base := base + lang.extra_fee; end if;
  end if;

  if p_citation_style_id is not null then
    select * into citation from citation_styles where id = p_citation_style_id and is_active = true;
    if citation is not null then base := base + citation.extra_fee; end if;
  end if;

  if p_additional_service_ids is not null then
    foreach addon_id in array p_additional_service_ids loop
      select * into addon from additional_services where id = addon_id and is_active = true;
      if addon is not null then
        if addon.price_type = 'fixed' then
          addons_total := addons_total + addon.price_value;
        else
          addons_total := addons_total + round(base * addon.price_value / 100, 2);
        end if;
        addons_breakdown := addons_breakdown || jsonb_build_object(
          'id', addon.id, 'name', addon.name, 'price_type', addon.price_type, 'price_value', addon.price_value
        );
      end if;
    end loop;
  end if;

  subtotal := base + addons_total;

  -- ---- gather discount candidates (evaluation only, nothing persisted) ----

  if p_user_id is not null then
    select email_verified into is_verified from profiles where id = p_user_id;
    if is_verified then
      select percentage into member_pct from discounts
       where type = 'member' and active = true
       order by created_at desc limit 1;
      if member_pct is not null then
        candidates := candidates || jsonb_build_object(
          'source', 'member', 'reference_id', null,
          'percentage', member_pct, 'amount', round(subtotal * member_pct / 100, 2)
        );
      end if;
    end if;
  end if;

  select * into early from discounts
   where type = 'early_order' and active = true
     and (start_date is null or start_date <= now())
     and (end_date is null or end_date >= now())
   order by created_at desc limit 1;
  if early is not null and early.percentage is not null then
    candidates := candidates || jsonb_build_object(
      'source', 'early_order', 'reference_id', early.id,
      'percentage', early.percentage, 'amount', round(subtotal * early.percentage / 100, 2)
    );
  end if;

  if p_referral_benefit_id is not null then
    select * into benefit from referral_benefits
     where id = p_referral_benefit_id
       and beneficiary_user_id = p_user_id
       and status = 'approved'
       and consumed_at is null
       and (expires_at is null or expires_at > now());
    if benefit is not null then
      candidates := candidates || jsonb_build_object(
        'source', 'referral', 'reference_id', benefit.id,
        'percentage', benefit.percentage, 'amount', round(subtotal * benefit.percentage / 100, 2)
      );
    end if;
  end if;

  if p_promo_code is not null and length(trim(p_promo_code)) > 0 then
    select * into promo from promo_codes
     where code = upper(trim(p_promo_code))
       and active = true
       and current_uses < max_total_uses
       and (expires_at is null or expires_at > now());
    if promo is not null then
      select * into promo_discount from discounts where id = promo.discount_id and active = true;
      if promo_discount is not null and (promo_discount.minimum_order is null or subtotal >= promo_discount.minimum_order) then
        cand := jsonb_build_object('source', 'promo', 'reference_id', promo.id);
        if promo_discount.percentage is not null then
          cand := cand || jsonb_build_object(
            'percentage', promo_discount.percentage,
            'amount', round(subtotal * promo_discount.percentage / 100, 2)
          );
        else
          cand := cand || jsonb_build_object('percentage', 0, 'amount', least(promo_discount.fixed_amount, subtotal));
        end if;
        candidates := candidates || cand;
      end if;
    end if;
  end if;

  -- cap each candidate at its discount's maximum_discount where applicable, then pick the single highest amount (no stacking)
  select c into best
    from (
      select c, (c->>'amount')::numeric as amt
      from jsonb_array_elements(candidates) c
      order by (c->>'amount')::numeric desc
      limit 1
    ) x;

  -- NOTE: the 'applied' key is only ever added when a discount actually won.
  -- jsonb_build_object('applied', best) with a SQL-NULL `best` would embed a
  -- JSON `null` token rather than omitting the key, and `x->'applied'`
  -- returns that non-SQL-NULL jsonb datum — breaking every downstream
  -- `is not null` check that assumes "no discount" means a true SQL NULL.
  return jsonb_build_object(
    'base_price', base,
    'addons_total', addons_total,
    'addons_breakdown', addons_breakdown,
    'subtotal', subtotal,
    'candidates', candidates,
    'final_price', subtotal - coalesce((best->>'amount')::numeric, 0)
  ) || case when best is not null then jsonb_build_object('applied', best) else '{}'::jsonb end;
end;
$$;

-- Client-facing, read-only preview entry point. Deliberately has no
-- p_user_id parameter — it always prices for the caller's own session
-- (auth.uid(), or null for a guest), so there is no field a malicious
-- client could set to preview, or leak eligibility for, another user.
create or replace function preview_price(
  p_service_id uuid,
  p_academic_level_id uuid,
  p_deadline_option_id uuid,
  p_word_count int,
  p_page_count numeric,
  p_language_id uuid,
  p_citation_style_id uuid,
  p_additional_service_ids uuid[],
  p_promo_code text
) returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_benefit_id uuid;
begin
  if v_user_id is not null then
    select id into v_benefit_id from referral_benefits
     where beneficiary_user_id = v_user_id and status = 'approved' and consumed_at is null
       and (expires_at is null or expires_at > now())
     order by created_at asc limit 1;
  end if;

  return calculate_price(
    p_service_id, p_academic_level_id, p_deadline_option_id, p_word_count, p_page_count,
    p_language_id, p_citation_style_id, p_additional_service_ids, v_user_id, p_promo_code, v_benefit_id
  );
end;
$$;

-- Read-only eligibility check used by the checkout UI to show
-- "code applied — pending" feedback without consuming or persisting anything.
create or replace function validate_promo_code(p_code text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case
    when pc.id is null then jsonb_build_object('valid', false, 'reason', 'not_found')
    when not pc.active then jsonb_build_object('valid', false, 'reason', 'inactive')
    when pc.expires_at is not null and pc.expires_at <= now() then jsonb_build_object('valid', false, 'reason', 'expired')
    when pc.current_uses >= pc.max_total_uses then jsonb_build_object('valid', false, 'reason', 'exhausted')
    else jsonb_build_object('valid', true, 'percentage', d.percentage, 'fixed_amount', d.fixed_amount)
  end
  from promo_codes pc
  left join discounts d on d.id = pc.discount_id
  where pc.code = upper(trim(p_code));
$$;

-- ---------- supabase/migrations/20260101000007_order_mutations.sql ----------
-- Narix Academy — order creation, guest claim, referral approval, status changes
--
-- All of these are SECURITY DEFINER functions: they are the only path by
-- which orders, referrals, and their financial fields are ever written.
-- Direct table INSERT is blocked by RLS for non-admin roles (see 000004),
-- so client code (server actions) must call these RPCs rather than
-- constructing inserts itself. This is what makes "the server always
-- recalculates, the client never writes a price" an enforced invariant
-- rather than a convention.

-- Redeems a referral code for one user against one order. Returns a short
-- status string ('pending_approval', 'not_found', 'self_referral_blocked',
-- 'already_used_by_user', 'exhausted') and NEVER raises — a lost race on a
-- concurrent duplicate redemption (unique_violation on
-- (referral_code_id, referred_user_id)) degrades to 'already_used_by_user'
-- rather than aborting the order that called it.
create or replace function redeem_referral_code(p_code text, p_user_id uuid, p_order_id uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ref_code_row referral_codes;
  v_referral_id uuid;
  v_default_pct numeric(5,2);
begin
  select * into v_ref_code_row from referral_codes where code = upper(trim(p_code));
  if v_ref_code_row is null then
    return 'not_found';
  end if;
  if v_ref_code_row.owner_user_id = p_user_id then
    return 'self_referral_blocked';
  end if;
  if exists (select 1 from referrals where referral_code_id = v_ref_code_row.id and referred_user_id = p_user_id) then
    return 'already_used_by_user';
  end if;
  if not try_consume_referral_code(v_ref_code_row.id) then
    return 'exhausted';
  end if;

  select coalesce((select percentage from discounts where type = 'referral' and active = true order by created_at desc limit 1), 10)
    into v_default_pct;

  begin
    insert into referrals (referral_code_id, referrer_user_id, referred_user_id, order_id)
    values (v_ref_code_row.id, v_ref_code_row.owner_user_id, p_user_id, p_order_id)
    returning id into v_referral_id;
  exception when unique_violation then
    return 'already_used_by_user';
  end;

  insert into referral_benefits (referral_id, beneficiary_user_id, benefit_type, percentage)
  values
    (v_referral_id, v_ref_code_row.owner_user_id, 'referrer_reward', v_default_pct),
    (v_referral_id, p_user_id, 'referred_discount', v_default_pct);

  perform enqueue_notification(
    p_user_id, 'referral_pending', 'Referral code applied',
    'Your referral discount is pending admin approval.', p_order_id
  );

  return 'pending_approval';
end;
$$;

create or replace function create_order(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Never trust a client-supplied user_id: a signed-in caller can only ever
  -- place an order as themselves, and an anonymous caller can only ever
  -- place a guest order. This is what makes it impossible for a client to
  -- create an order under someone else's account or borrow their member
  -- discount by passing an arbitrary user_id in the payload.
  v_user_id uuid := auth.uid();
  v_guest_name text := p_payload->>'guest_name';
  v_guest_email text := p_payload->>'guest_email';
  v_guest_phone text := p_payload->>'guest_phone';
  v_service_id uuid := (p_payload->>'service_id')::uuid;
  v_academic_level_id uuid := (p_payload->>'academic_level_id')::uuid;
  v_deadline_option_id uuid := (p_payload->>'deadline_option_id')::uuid;
  v_word_count_option_id uuid := (p_payload->>'word_count_option_id')::uuid;
  v_word_count int := (p_payload->>'word_count')::int;
  v_page_count numeric := (p_payload->>'page_count')::numeric;
  v_language_id uuid := (p_payload->>'language_id')::uuid;
  v_citation_style_id uuid := (p_payload->>'citation_style_id')::uuid;
  v_addon_ids uuid[];
  v_subject text := p_payload->>'subject';
  v_topic text := p_payload->>'topic';
  v_description text := p_payload->>'description';
  v_promo_code text := p_payload->>'promo_code';
  v_referral_code text := p_payload->>'referral_code';

  v_pricing jsonb;
  v_existing_benefit_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_status_id uuid;
  v_raw_token text;
  v_token_hash text;
  v_addon jsonb;
  v_cand jsonb;
  v_applied jsonb;
  v_referral_note text := null;
  admin_row record;
begin
  if v_user_id is null and (v_guest_email is null or length(trim(v_guest_email)) = 0) then
    raise exception 'GUEST_EMAIL_REQUIRED' using errcode = 'P0001';
  end if;

  select array_agg(value::uuid) into v_addon_ids
  from jsonb_array_elements_text(coalesce(p_payload->'additional_service_ids', '[]'::jsonb));

  -- A registered user may already be holding an approved, unconsumed
  -- referral benefit (typically the referrer's reward) — surface it as a
  -- candidate automatically so it can be picked if it's the best discount.
  if v_user_id is not null then
    select id into v_existing_benefit_id from referral_benefits
     where beneficiary_user_id = v_user_id and status = 'approved' and consumed_at is null
       and (expires_at is null or expires_at > now())
     order by created_at asc limit 1;
  end if;

  v_pricing := calculate_price(
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count, v_page_count,
    v_language_id, v_citation_style_id, v_addon_ids, v_user_id, v_promo_code, v_existing_benefit_id
  );

  v_applied := v_pricing->'applied';

  -- Atomically consume whatever won, inside this same transaction. If the
  -- consumption fails (lost a race for the last use), abort the whole order
  -- rather than silently charging a price that assumed a discount which no
  -- longer applies.
  if v_applied is not null then
    if v_applied->>'source' = 'promo' then
      if not try_consume_promo_code((v_applied->>'reference_id')::uuid) then
        raise exception 'PROMO_CODE_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    elsif v_applied->>'source' = 'referral' then
      update referral_benefits
         set status = 'consumed', consumed_at = now()
       where id = (v_applied->>'reference_id')::uuid
         and status = 'approved' and consumed_at is null
      returning id into v_existing_benefit_id;
      if v_existing_benefit_id is null then
        raise exception 'REFERRAL_BENEFIT_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    end if;
  end if;

  select id into v_status_id from order_statuses where slug = 'new_order' and is_active = true;
  v_order_number := next_order_number();

  if v_user_id is null then
    v_raw_token := encode(gen_random_bytes(32), 'hex');
    v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');
  end if;

  insert into orders (
    order_number, user_id, guest_name, guest_email, guest_phone, guest_token_hash,
    service_id, academic_level_id, deadline_option_id, word_count_option_id,
    word_count, page_count, language_id, citation_style_id,
    subject, topic, description,
    base_price, discount_source, discount_percentage, discount_amount, final_price,
    status_id
  ) values (
    v_order_number, v_user_id, v_guest_name, v_guest_email, v_guest_phone, v_token_hash,
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count_option_id,
    v_word_count, v_page_count, v_language_id, v_citation_style_id,
    v_subject, v_topic, v_description,
    (v_pricing->>'base_price')::numeric,
    case when v_applied is not null then (v_applied->>'source')::discount_type else null end,
    coalesce((v_applied->>'percentage')::numeric, 0),
    coalesce((v_applied->>'amount')::numeric, 0),
    (v_pricing->>'final_price')::numeric,
    v_status_id
  ) returning id into v_order_id;

  insert into order_pricing_snapshots (order_id, snapshot, config_version)
  values (v_order_id, v_pricing, to_char(now(), 'YYYYMMDDHH24MISS'));

  for v_addon in select * from jsonb_array_elements(coalesce(v_pricing->'addons_breakdown', '[]'::jsonb)) loop
    insert into order_additional_services (order_id, additional_service_id, name_at_order, price_at_order)
    values (v_order_id, (v_addon->>'id')::uuid, v_addon->>'name',
      case when v_addon->>'price_type' = 'fixed' then (v_addon->>'price_value')::numeric
           else round((v_pricing->>'base_price')::numeric * (v_addon->>'price_value')::numeric / 100, 2) end);
  end loop;

  for v_cand in select * from jsonb_array_elements(coalesce(v_pricing->'candidates', '[]'::jsonb)) loop
    insert into discount_applications (order_id, discount_source, reference_id, percentage_considered, amount_considered, applied, reason)
    values (
      v_order_id, (v_cand->>'source')::discount_type, (v_cand->>'reference_id')::uuid,
      (v_cand->>'percentage')::numeric, (v_cand->>'amount')::numeric,
      v_applied is not null and v_cand = v_applied,
      case when v_applied is not null and v_cand = v_applied then 'highest value candidate'
           else 'lower value than applied ' || coalesce(v_applied->>'source', 'discount') end
    );
  end loop;

  insert into order_status_history (order_id, from_status_id, to_status_id, note)
  values (v_order_id, null, v_status_id, 'Order created');

  -- Referral code entered at checkout: creates a pending-approval referral,
  -- never affects this order's price directly.
  if v_referral_code is not null and length(trim(v_referral_code)) > 0 and v_user_id is not null then
    v_referral_note := redeem_referral_code(v_referral_code, v_user_id, v_order_id);
  end if;

  if v_user_id is not null then
    perform enqueue_notification(v_user_id, 'order_created', 'Order ' || v_order_number || ' received', 'We have received your order.', v_order_id);
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', v_user_id, profile_email(v_user_id), jsonb_build_object('order_number', v_order_number));
  else
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', null, v_guest_email, jsonb_build_object('order_number', v_order_number));
  end if;

  for admin_row in select id from profiles where role = 'admin' loop
    perform enqueue_notification(admin_row.id, 'new_order', 'New order ' || v_order_number, 'A new order was submitted.', v_order_id);
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'final_price', v_pricing->>'final_price',
    'guest_token', v_raw_token,
    'referral_status', v_referral_note
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- Guest tracking (by token) and guest -> account claim
-- ---------------------------------------------------------------------------

create or replace function get_order_by_token(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_hash text := encode(digest(p_token, 'sha256'), 'hex');
  o orders;
  result jsonb;
begin
  select * into o from orders where guest_token_hash = v_hash;
  if o is null then
    return null;
  end if;

  select jsonb_build_object(
    'order_number', o.order_number,
    'status', (select jsonb_build_object('name', name, 'color', color, 'slug', slug) from order_statuses where id = o.status_id),
    'final_price', o.final_price,
    'paid_amount', o.paid_amount,
    'remaining_amount', o.remaining_amount,
    'is_fully_paid', o.is_fully_paid,
    'created_at', o.created_at,
    'claimed', o.user_id is not null,
    'timeline', (
      select coalesce(jsonb_agg(jsonb_build_object('status', s.name, 'color', s.color, 'note', h.note, 'created_at', h.created_at) order by h.created_at)
      , '[]'::jsonb)
      from order_status_history h join order_statuses s on s.id = h.to_status_id
      where h.order_id = o.id
    )
  ) into result;

  return result;
end;
$$;

-- Guest -> account claim. Requires: the requester is signed in AND verified,
-- AND holds the guest tracking token. Email match alone is never sufficient.
create or replace function claim_guest_order(p_order_number text, p_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_hash text := encode(digest(p_token, 'sha256'), 'hex');
  o orders;
  requester profiles;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = 'P0001';
  end if;

  select * into requester from profiles where id = auth.uid();
  if requester is null or requester.email_verified = false then
    raise exception 'EMAIL_NOT_VERIFIED' using errcode = 'P0001';
  end if;

  select * into o from orders where order_number = p_order_number and guest_token_hash = v_hash;
  if o is null then
    raise exception 'INVALID_ORDER_OR_TOKEN' using errcode = 'P0001';
  end if;
  if o.user_id is not null then
    raise exception 'ALREADY_CLAIMED' using errcode = 'P0001';
  end if;

  update orders set user_id = auth.uid(), claimed_at = now() where id = o.id;

  insert into audit_logs (actor_id, action, entity_type, entity_id, before, after)
  values (auth.uid(), 'claim', 'orders', o.id::text, jsonb_build_object('user_id', null), jsonb_build_object('user_id', auth.uid()));

  return jsonb_build_object('order_id', o.id, 'order_number', o.order_number);
end;
$$;

-- ---------------------------------------------------------------------------
-- Referral approval / rejection
-- ---------------------------------------------------------------------------

create or replace function reevaluate_order_discount(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  o orders;
  v_pricing jsonb;
  v_applied jsonb;
  v_best_benefit_id uuid;
  v_cand jsonb;
begin
  select * into o from orders where id = p_order_id;
  if o is null or o.locked then
    return; -- order already closed out; the benefit stays available for a future order
  end if;

  select id into v_best_benefit_id from referral_benefits
   where beneficiary_user_id = o.user_id and status = 'approved' and consumed_at is null
     and (expires_at is null or expires_at > now())
   order by created_at asc limit 1;

  v_pricing := calculate_price(
    o.service_id, o.academic_level_id, o.deadline_option_id, o.word_count, o.page_count,
    o.language_id, o.citation_style_id,
    (select array_agg(additional_service_id) from order_additional_services where order_id = o.id),
    o.user_id, null, v_best_benefit_id
  );
  v_applied := v_pricing->'applied';

  if v_applied is not null and v_applied->>'source' = 'referral'
     and coalesce((v_applied->>'amount')::numeric, 0) > o.discount_amount then
    update referral_benefits set status = 'consumed', consumed_order_id = o.id, consumed_at = now()
     where id = v_best_benefit_id;

    update orders set
      discount_source = 'referral',
      discount_percentage = (v_applied->>'percentage')::numeric,
      discount_amount = (v_applied->>'amount')::numeric,
      final_price = (v_pricing->>'final_price')::numeric
    where id = o.id;

    for v_cand in select * from jsonb_array_elements(coalesce(v_pricing->'candidates', '[]'::jsonb)) loop
      insert into discount_applications (order_id, discount_source, reference_id, percentage_considered, amount_considered, applied, reason)
      values (o.id, (v_cand->>'source')::discount_type, (v_cand->>'reference_id')::uuid,
        (v_cand->>'percentage')::numeric, (v_cand->>'amount')::numeric,
        v_cand = v_applied, 'referral approval re-evaluation');
    end loop;
  end if;
end;
$$;

create or replace function approve_referral(p_referral_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r referrals;
  validity_days int;
begin
  if not is_admin() then
    raise exception 'FORBIDDEN' using errcode = 'P0001';
  end if;

  select * into r from referrals where id = p_referral_id and status = 'pending_approval';
  if r is null then
    raise exception 'REFERRAL_NOT_PENDING' using errcode = 'P0001';
  end if;

  select coalesce((value->>'validity_days')::int, 90) into validity_days
  from site_settings where key = 'referral_program';

  update referrals set status = 'approved', approved_by = auth.uid(), approved_at = now() where id = p_referral_id;

  update referral_benefits
     set status = 'approved', approved_by = auth.uid(), approved_at = now(),
         expires_at = now() + (coalesce(validity_days, 90) || ' days')::interval
   where referral_id = p_referral_id;

  perform reevaluate_order_discount(r.order_id);

  perform enqueue_notification(r.referrer_user_id, 'referral_approved', 'Referral approved', 'Your referral reward is ready to use on your next order.', null);
  perform enqueue_notification(r.referred_user_id, 'referral_approved', 'Referral discount approved', 'Your referral discount has been approved.', r.order_id);
  perform enqueue_email_job('referral_approved', 'referral_approved:referrer:' || p_referral_id::text, 'referral_approved', r.referrer_user_id, profile_email(r.referrer_user_id), '{}'::jsonb);
  perform enqueue_email_job('referral_approved', 'referral_approved:referred:' || p_referral_id::text, 'referral_approved', r.referred_user_id, profile_email(r.referred_user_id), '{}'::jsonb);

  insert into audit_logs (actor_id, action, entity_type, entity_id, after)
  values (auth.uid(), 'approve', 'referrals', p_referral_id::text, jsonb_build_object('status', 'approved'));

  return jsonb_build_object('status', 'approved');
end;
$$;

create or replace function reject_referral(p_referral_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r referrals;
begin
  if not is_admin() then
    raise exception 'FORBIDDEN' using errcode = 'P0001';
  end if;

  select * into r from referrals where id = p_referral_id and status = 'pending_approval';
  if r is null then
    raise exception 'REFERRAL_NOT_PENDING' using errcode = 'P0001';
  end if;

  update referrals set status = 'rejected', rejected_reason = p_reason, approved_by = auth.uid(), approved_at = now() where id = p_referral_id;
  update referral_benefits set status = 'rejected' where referral_id = p_referral_id;

  perform enqueue_notification(r.referred_user_id, 'referral_rejected', 'Referral discount rejected', coalesce(p_reason, 'Your referral discount request was not approved.'), r.order_id);
  perform enqueue_email_job('referral_rejected', 'referral_rejected:' || p_referral_id::text, 'referral_rejected', r.referred_user_id, profile_email(r.referred_user_id), jsonb_build_object('reason', p_reason));

  insert into audit_logs (actor_id, action, entity_type, entity_id, after)
  values (auth.uid(), 'reject', 'referrals', p_referral_id::text, jsonb_build_object('status', 'rejected', 'reason', p_reason));

  return jsonb_build_object('status', 'rejected');
end;
$$;

-- ---------------------------------------------------------------------------
-- Order status transitions
-- ---------------------------------------------------------------------------

create or replace function change_order_status(p_order_id uuid, p_new_status_id uuid, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  o orders;
  new_status order_statuses;
begin
  if not is_admin() then
    raise exception 'FORBIDDEN' using errcode = 'P0001';
  end if;

  select * into o from orders where id = p_order_id;
  if o is null then
    raise exception 'ORDER_NOT_FOUND' using errcode = 'P0001';
  end if;
  if o.locked then
    raise exception 'ORDER_LOCKED' using errcode = 'P0001';
  end if;

  select * into new_status from order_statuses where id = p_new_status_id and is_active = true;
  if new_status is null then
    raise exception 'INVALID_STATUS' using errcode = 'P0001';
  end if;

  update orders set status_id = p_new_status_id, locked = new_status.is_terminal
   where id = p_order_id and status_id = o.status_id; -- optimistic: no-op if status changed concurrently

  if not found then
    raise exception 'CONCURRENT_STATUS_CHANGE' using errcode = 'P0001';
  end if;

  insert into order_status_history (order_id, from_status_id, to_status_id, changed_by, note)
  values (p_order_id, o.status_id, p_new_status_id, auth.uid(), p_note);

  return jsonb_build_object('status', new_status.slug);
end;
$$;

create or replace function unlock_order(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not is_admin() then
    raise exception 'FORBIDDEN' using errcode = 'P0001';
  end if;
  update orders set locked = false where id = p_order_id;
  insert into audit_logs (actor_id, action, entity_type, entity_id)
  values (auth.uid(), 'unlock', 'orders', p_order_id::text);
end;
$$;

-- ---------- supabase/migrations/20260101000008_function_grants.sql ----------
-- Narix Academy — function execute grants
--
-- Postgres grants EXECUTE on every newly created function to PUBLIC by
-- default. Left alone, that means every SECURITY DEFINER function above —
-- including internal helpers that trust their parameters, such as
-- calculate_price(p_user_id, ...) or try_consume_referral_code(p_code_id) —
-- would be directly callable over PostgREST by any anon/authenticated
-- client, who could pass whatever arguments they like. We revoke that
-- default for every function in this schema, then grant EXECUTE back only
-- on the specific functions meant to be public entry points.
--
-- Supabase projects additionally run `ALTER DEFAULT PRIVILEGES IN SCHEMA
-- public GRANT EXECUTE ON FUNCTIONS TO anon, authenticated` at the database
-- level, so every new function is auto-granted to those two roles
-- specifically — not just to the generic PUBLIC pseudo-role. Revoking only
-- `FROM PUBLIC` therefore leaves that Supabase-level grant standing. Both
-- must be revoked explicitly.

revoke execute on all functions in schema public from public, anon, authenticated;

-- Needed by RLS policies themselves (evaluated as the querying role for
-- every request), not just by application code — must stay open.
grant execute on function is_admin() to anon, authenticated;
grant execute on function owns_order(uuid) to anon, authenticated;

-- Client-facing, safe-by-construction entry points (each ignores/derives
-- any caller identity from auth.uid() rather than trusting a parameter).
grant execute on function preview_price(uuid, uuid, uuid, int, numeric, uuid, uuid, uuid[], text) to anon, authenticated;
grant execute on function validate_promo_code(text) to anon, authenticated;
grant execute on function create_order(jsonb) to anon, authenticated;
grant execute on function get_order_by_token(text) to anon, authenticated;
grant execute on function claim_guest_order(text, text) to authenticated;
grant execute on function approve_referral(uuid) to authenticated;
grant execute on function reject_referral(uuid, text) to authenticated;
grant execute on function change_order_status(uuid, uuid, text) to authenticated;
grant execute on function unlock_order(uuid) to authenticated;

-- Everything else (calculate_price, redeem_referral_code, try_consume_*,
-- enqueue_*, profile_email, next_order_number, generate_referral_code,
-- reevaluate_order_discount, all trigger functions, etc.) is intentionally
-- left unreachable via RPC — only callable from inside another SECURITY
-- DEFINER function, which executes as the function owner and is therefore
-- unaffected by this revoke.

-- ---------- supabase/migrations/20260101000009_storage.sql ----------
-- Narix Academy — private file storage
--
-- Single private bucket. Path convention: orders/{order_id}/{category}/{filename}
-- so ownership can be checked straight from the path, mirroring owns_order().

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'order-files', 'order-files', false, 26214400, -- 25MB
  array[
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'image/png', 'image/jpeg', 'image/webp',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/csv'
  ]
)
on conflict (id) do nothing;

-- storage.objects.name for this bucket looks like: orders/<order_id>/<category>/<uuid>-<filename>
create or replace function storage_path_order_id(p_name text)
returns uuid
language sql
immutable
as $$
  select case
    when p_name ~ '^orders/[0-9a-fA-F-]{36}/'
      then split_part(p_name, '/', 2)::uuid
    else null
  end;
$$;

create policy order_files_select on storage.objects
  for select using (
    bucket_id = 'order-files'
    and (owns_order(storage_path_order_id(name)) or is_admin())
  );

create policy order_files_insert on storage.objects
  for insert with check (
    bucket_id = 'order-files'
    and (owns_order(storage_path_order_id(name)) or is_admin())
  );

create policy order_files_delete on storage.objects
  for delete using (
    bucket_id = 'order-files' and is_admin()
  );

-- ---------- supabase/migrations/20260101000010_order_institution_fields.sql ----------
-- Narix Academy — optional institution fields on orders
--
-- Informational only (never affects pricing). Free text so a student can
-- either pick from a client-side reference list or type their own — the
-- server does not validate against a fixed list.

alter table orders add column if not exists university text;
alter table orders add column if not exists college text;

create or replace function create_order(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_guest_name text := p_payload->>'guest_name';
  v_guest_email text := p_payload->>'guest_email';
  v_guest_phone text := p_payload->>'guest_phone';
  v_service_id uuid := (p_payload->>'service_id')::uuid;
  v_academic_level_id uuid := (p_payload->>'academic_level_id')::uuid;
  v_deadline_option_id uuid := (p_payload->>'deadline_option_id')::uuid;
  v_word_count_option_id uuid := (p_payload->>'word_count_option_id')::uuid;
  v_word_count int := (p_payload->>'word_count')::int;
  v_page_count numeric := (p_payload->>'page_count')::numeric;
  v_language_id uuid := (p_payload->>'language_id')::uuid;
  v_citation_style_id uuid := (p_payload->>'citation_style_id')::uuid;
  v_addon_ids uuid[];
  v_subject text := p_payload->>'subject';
  v_topic text := p_payload->>'topic';
  v_description text := p_payload->>'description';
  v_university text := p_payload->>'university';
  v_college text := p_payload->>'college';
  v_promo_code text := p_payload->>'promo_code';
  v_referral_code text := p_payload->>'referral_code';

  v_pricing jsonb;
  v_existing_benefit_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_status_id uuid;
  v_raw_token text;
  v_token_hash text;
  v_addon jsonb;
  v_cand jsonb;
  v_applied jsonb;
  v_referral_note text := null;
  admin_row record;
begin
  if v_user_id is null and (v_guest_email is null or length(trim(v_guest_email)) = 0) then
    raise exception 'GUEST_EMAIL_REQUIRED' using errcode = 'P0001';
  end if;

  select array_agg(value::uuid) into v_addon_ids
  from jsonb_array_elements_text(coalesce(p_payload->'additional_service_ids', '[]'::jsonb));

  if v_user_id is not null then
    select id into v_existing_benefit_id from referral_benefits
     where beneficiary_user_id = v_user_id and status = 'approved' and consumed_at is null
       and (expires_at is null or expires_at > now())
     order by created_at asc limit 1;
  end if;

  v_pricing := calculate_price(
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count, v_page_count,
    v_language_id, v_citation_style_id, v_addon_ids, v_user_id, v_promo_code, v_existing_benefit_id
  );

  v_applied := v_pricing->'applied';

  if v_applied is not null then
    if v_applied->>'source' = 'promo' then
      if not try_consume_promo_code((v_applied->>'reference_id')::uuid) then
        raise exception 'PROMO_CODE_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    elsif v_applied->>'source' = 'referral' then
      update referral_benefits
         set status = 'consumed', consumed_at = now()
       where id = (v_applied->>'reference_id')::uuid
         and status = 'approved' and consumed_at is null
      returning id into v_existing_benefit_id;
      if v_existing_benefit_id is null then
        raise exception 'REFERRAL_BENEFIT_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    end if;
  end if;

  select id into v_status_id from order_statuses where slug = 'new_order' and is_active = true;
  v_order_number := next_order_number();

  if v_user_id is null then
    v_raw_token := encode(gen_random_bytes(32), 'hex');
    v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');
  end if;

  insert into orders (
    order_number, user_id, guest_name, guest_email, guest_phone, guest_token_hash,
    service_id, academic_level_id, deadline_option_id, word_count_option_id,
    word_count, page_count, language_id, citation_style_id,
    subject, topic, description, university, college,
    base_price, discount_source, discount_percentage, discount_amount, final_price,
    status_id
  ) values (
    v_order_number, v_user_id, v_guest_name, v_guest_email, v_guest_phone, v_token_hash,
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count_option_id,
    v_word_count, v_page_count, v_language_id, v_citation_style_id,
    v_subject, v_topic, v_description, v_university, v_college,
    (v_pricing->>'base_price')::numeric,
    case when v_applied is not null then (v_applied->>'source')::discount_type else null end,
    coalesce((v_applied->>'percentage')::numeric, 0),
    coalesce((v_applied->>'amount')::numeric, 0),
    (v_pricing->>'final_price')::numeric,
    v_status_id
  ) returning id into v_order_id;

  insert into order_pricing_snapshots (order_id, snapshot, config_version)
  values (v_order_id, v_pricing, to_char(now(), 'YYYYMMDDHH24MISS'));

  for v_addon in select * from jsonb_array_elements(coalesce(v_pricing->'addons_breakdown', '[]'::jsonb)) loop
    insert into order_additional_services (order_id, additional_service_id, name_at_order, price_at_order)
    values (v_order_id, (v_addon->>'id')::uuid, v_addon->>'name',
      case when v_addon->>'price_type' = 'fixed' then (v_addon->>'price_value')::numeric
           else round((v_pricing->>'base_price')::numeric * (v_addon->>'price_value')::numeric / 100, 2) end);
  end loop;

  for v_cand in select * from jsonb_array_elements(coalesce(v_pricing->'candidates', '[]'::jsonb)) loop
    insert into discount_applications (order_id, discount_source, reference_id, percentage_considered, amount_considered, applied, reason)
    values (
      v_order_id, (v_cand->>'source')::discount_type, (v_cand->>'reference_id')::uuid,
      (v_cand->>'percentage')::numeric, (v_cand->>'amount')::numeric,
      v_applied is not null and v_cand = v_applied,
      case when v_applied is not null and v_cand = v_applied then 'highest value candidate'
           else 'lower value than applied ' || coalesce(v_applied->>'source', 'discount') end
    );
  end loop;

  insert into order_status_history (order_id, from_status_id, to_status_id, note)
  values (v_order_id, null, v_status_id, 'Order created');

  if v_referral_code is not null and length(trim(v_referral_code)) > 0 and v_user_id is not null then
    v_referral_note := redeem_referral_code(v_referral_code, v_user_id, v_order_id);
  end if;

  if v_user_id is not null then
    perform enqueue_notification(v_user_id, 'order_created', 'Order ' || v_order_number || ' received', 'We have received your order.', v_order_id);
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', v_user_id, profile_email(v_user_id), jsonb_build_object('order_number', v_order_number));
  else
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', null, v_guest_email, jsonb_build_object('order_number', v_order_number));
  end if;

  for admin_row in select id from profiles where role = 'admin' loop
    perform enqueue_notification(admin_row.id, 'new_order', 'New order ' || v_order_number, 'A new order was submitted.', v_order_id);
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'final_price', v_pricing->>'final_price',
    'guest_token', v_raw_token,
    'referral_status', v_referral_note
  );
end;
$$;

-- ---------- supabase/migrations/20260101000011_service_pricing_rules.sql ----------
-- Narix Academy — per-service pricing rules (replaces pricing_rules for
-- price calculation)
--
-- The business now prices purely by (service, page_count) — never by
-- academic level, and never multiplied by deadline. `pricing_rules`
-- (service x academic_level, linear base+per_page) cannot express the two
-- required shapes:
--   - progressive: a flat or linear "base tier" price for the first N
--     pages, then a different per-page rate beyond N (Essay/Presentation
--     use a flat base tier; Thesis uses a linear one)
--   - per_page: a straight per-page rate with an enforced minimum page
--     count (Dissertation, Buraxılış İşi)
-- `pricing_rules` is left in place (unreferenced by calculate_price from
-- this migration onward) rather than dropped, to avoid a destructive
-- change against a live table — but it no longer has any effect on price.

create table service_pricing_rules (
  service_id uuid primary key references services(id) on delete cascade,
  pricing_type text not null check (pricing_type in ('progressive', 'per_page')),

  -- progressive
  base_pages int,
  base_mode text check (base_mode in ('flat', 'linear')),
  base_price numeric(10,2),
  additional_page_price numeric(10,2),

  -- per_page
  price_per_page numeric(10,2),
  minimum_pages int,

  updated_at timestamptz not null default now(),

  constraint progressive_fields_required check (
    pricing_type <> 'progressive' or
    (base_pages is not null and base_mode is not null and base_price is not null and additional_page_price is not null)
  ),
  constraint per_page_fields_required check (
    pricing_type <> 'per_page' or price_per_page is not null
  )
);

alter table service_pricing_rules enable row level security;

create policy service_pricing_rules_read on service_pricing_rules for select using (true);
create policy service_pricing_rules_write on service_pricing_rules for all using (is_admin()) with check (is_admin());

create trigger set_updated_at before update on service_pricing_rules
  for each row execute function set_updated_at();

-- service_pricing_rules keys on service_id, not id, so (like site_settings)
-- it gets its own audit trigger rather than the generic one.
create or replace function log_service_pricing_rules_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into audit_logs (actor_id, action, entity_type, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op),
    'service_pricing_rules',
    coalesce(new.service_id::text, old.service_id::text),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('UPDATE','INSERT') then to_jsonb(new) else null end
  );
  return coalesce(new, old);
end;
$$;

create trigger audit_service_pricing_rules after insert or update or delete on service_pricing_rules
  for each row execute function log_service_pricing_rules_change();

-- ---------------------------------------------------------------------------
-- calculate_price() — base price now comes from service_pricing_rules only.
-- Deadline no longer multiplies the price (previously `base * deadline
-- .multiplier + deadline.fixed_fee`); the deadline is still a required,
-- validated selection on the order (delivery-time information), it simply
-- no longer affects the total. Academic level is likewise still recorded
-- on the order but no longer read for pricing.
-- ---------------------------------------------------------------------------

create or replace function calculate_price(
  p_service_id uuid,
  p_academic_level_id uuid,
  p_deadline_option_id uuid,
  p_word_count int,
  p_page_count numeric,
  p_language_id uuid,
  p_citation_style_id uuid,
  p_additional_service_ids uuid[],
  p_user_id uuid,
  p_promo_code text,
  p_referral_benefit_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rule service_pricing_rules;
  pages int;
  lang languages;
  citation citation_styles;
  addon additional_services;
  addon_id uuid;
  base numeric(10,2);
  addons_total numeric(10,2) := 0;
  addons_breakdown jsonb := '[]'::jsonb;
  subtotal numeric(10,2);
  candidates jsonb := '[]'::jsonb;
  best jsonb := null;
  cand jsonb;
  member_pct numeric(5,2);
  early discounts;
  promo promo_codes;
  promo_discount discounts;
  benefit referral_benefits;
  is_verified boolean;
begin
  if not exists (select 1 from academic_levels where id = p_academic_level_id and is_active = true) then
    raise exception 'INVALID_ACADEMIC_LEVEL' using errcode = 'P0001';
  end if;
  if not exists (select 1 from deadline_options where id = p_deadline_option_id and is_active = true) then
    raise exception 'INVALID_DEADLINE' using errcode = 'P0001';
  end if;

  -- Pages must be a positive whole number — no decimals, no zero/negative.
  if p_page_count is null or p_page_count <> trunc(p_page_count) or p_page_count < 1 then
    raise exception 'INVALID_PAGE_COUNT' using errcode = 'P0001';
  end if;
  pages := p_page_count::int;

  select * into rule from service_pricing_rules where service_id = p_service_id;
  if rule is null then
    raise exception 'NO_PRICING_RULE' using errcode = 'P0001';
  end if;

  if rule.pricing_type = 'per_page' then
    if rule.minimum_pages is not null and pages < rule.minimum_pages then
      raise exception 'BELOW_MINIMUM_PAGES:%', rule.minimum_pages using errcode = 'P0001';
    end if;
    base := pages * rule.price_per_page;
  else
    if pages <= rule.base_pages then
      base := case when rule.base_mode = 'flat' then rule.base_price else pages * rule.base_price end;
    else
      base := (case when rule.base_mode = 'flat' then rule.base_price else rule.base_pages * rule.base_price end)
              + (pages - rule.base_pages) * rule.additional_page_price;
    end if;
  end if;

  if p_language_id is not null then
    select * into lang from languages where id = p_language_id and is_active = true;
    if lang is not null then base := base + lang.extra_fee; end if;
  end if;

  if p_citation_style_id is not null then
    select * into citation from citation_styles where id = p_citation_style_id and is_active = true;
    if citation is not null then base := base + citation.extra_fee; end if;
  end if;

  if p_additional_service_ids is not null then
    foreach addon_id in array p_additional_service_ids loop
      select * into addon from additional_services where id = addon_id and is_active = true;
      if addon is not null then
        if addon.price_type = 'fixed' then
          addons_total := addons_total + addon.price_value;
        else
          addons_total := addons_total + round(base * addon.price_value / 100, 2);
        end if;
        addons_breakdown := addons_breakdown || jsonb_build_object(
          'id', addon.id, 'name', addon.name, 'price_type', addon.price_type, 'price_value', addon.price_value
        );
      end if;
    end loop;
  end if;

  subtotal := base + addons_total;

  -- ---- gather discount candidates (evaluation only, nothing persisted) ----

  if p_user_id is not null then
    select email_verified into is_verified from profiles where id = p_user_id;
    if is_verified then
      select percentage into member_pct from discounts
       where type = 'member' and active = true
       order by created_at desc limit 1;
      if member_pct is not null then
        candidates := candidates || jsonb_build_object(
          'source', 'member', 'reference_id', null,
          'percentage', member_pct, 'amount', round(subtotal * member_pct / 100, 2)
        );
      end if;
    end if;
  end if;

  select * into early from discounts
   where type = 'early_order' and active = true
     and (start_date is null or start_date <= now())
     and (end_date is null or end_date >= now())
   order by created_at desc limit 1;
  if early is not null and early.percentage is not null then
    candidates := candidates || jsonb_build_object(
      'source', 'early_order', 'reference_id', early.id,
      'percentage', early.percentage, 'amount', round(subtotal * early.percentage / 100, 2)
    );
  end if;

  if p_referral_benefit_id is not null then
    select * into benefit from referral_benefits
     where id = p_referral_benefit_id
       and beneficiary_user_id = p_user_id
       and status = 'approved'
       and consumed_at is null
       and (expires_at is null or expires_at > now());
    if benefit is not null then
      candidates := candidates || jsonb_build_object(
        'source', 'referral', 'reference_id', benefit.id,
        'percentage', benefit.percentage, 'amount', round(subtotal * benefit.percentage / 100, 2)
      );
    end if;
  end if;

  if p_promo_code is not null and length(trim(p_promo_code)) > 0 then
    select * into promo from promo_codes
     where code = upper(trim(p_promo_code))
       and active = true
       and current_uses < max_total_uses
       and (expires_at is null or expires_at > now());
    if promo is not null then
      select * into promo_discount from discounts where id = promo.discount_id and active = true;
      if promo_discount is not null and (promo_discount.minimum_order is null or subtotal >= promo_discount.minimum_order) then
        cand := jsonb_build_object('source', 'promo', 'reference_id', promo.id);
        if promo_discount.percentage is not null then
          cand := cand || jsonb_build_object(
            'percentage', promo_discount.percentage,
            'amount', round(subtotal * promo_discount.percentage / 100, 2)
          );
        else
          cand := cand || jsonb_build_object('percentage', 0, 'amount', least(promo_discount.fixed_amount, subtotal));
        end if;
        candidates := candidates || cand;
      end if;
    end if;
  end if;

  select c into best
    from (
      select c, (c->>'amount')::numeric as amt
      from jsonb_array_elements(candidates) c
      order by (c->>'amount')::numeric desc
      limit 1
    ) x;

  return jsonb_build_object(
    'base_price', base,
    'addons_total', addons_total,
    'addons_breakdown', addons_breakdown,
    'subtotal', subtotal,
    'candidates', candidates,
    'final_price', subtotal - coalesce((best->>'amount')::numeric, 0)
  ) || case when best is not null then jsonb_build_object('applied', best) else '{}'::jsonb end;
end;
$$;

-- ---------- supabase/migrations/20260101000012_content_translations.sql ----------
-- Narix Academy — per-locale content overrides
--
-- service_categories/services/academic_levels/deadline_options/languages/
-- additional_services store their base text in Azerbaijani (the site
-- default). `translations` holds locale-keyed overrides, e.g.
-- {"en": {"name": "Essay", "description": "..."}} — a key/field is only
-- present when it actually differs from the AZ base column, so the app can
-- always fall back to the base column for any locale/field it doesn't find.

alter table service_categories add column if not exists translations jsonb not null default '{}'::jsonb;
alter table services add column if not exists translations jsonb not null default '{}'::jsonb;
alter table academic_levels add column if not exists translations jsonb not null default '{}'::jsonb;
alter table deadline_options add column if not exists translations jsonb not null default '{}'::jsonb;
alter table languages add column if not exists translations jsonb not null default '{}'::jsonb;
alter table additional_services add column if not exists translations jsonb not null default '{}'::jsonb;

-- ---------------------------------------------------------------------------
-- English overrides for the seeded content
-- ---------------------------------------------------------------------------

update service_categories set translations = jsonb_build_object('en', jsonb_build_object('name', v.name_en))
from (values ('writing', 'Writing'), ('editing-review', 'Editing & Review'), ('research-data', 'Research & Data'))
  as v(slug, name_en)
where service_categories.slug = v.slug;

update services set translations = jsonb_build_object('en', jsonb_build_object('name', v.name_en, 'description', v.description_en))
from (values
  ('essay', 'Essay', 'Custom essays across subjects and citation styles.'),
  ('research-paper', 'Research Paper', 'In-depth research papers with full source work.'),
  ('thesis', 'Thesis', 'Thesis writing support.'),
  ('graduation-project', 'Graduation Project', 'Full writing of your graduation (qualification) project.'),
  ('dissertation', 'Dissertation', 'Dissertation chapters and full manuscripts.'),
  ('editing', 'Editing', 'Line and structural editing of existing drafts.'),
  ('proofreading', 'Proofreading', 'Grammar, clarity and formatting pass.'),
  ('translation', 'Translation', 'Academic translation between languages.'),
  ('paraphrasing', 'Paraphrasing', 'Original, clear rewriting of existing text.'),
  ('data-analysis', 'Data Analysis', 'Statistical analysis and interpretation.'),
  ('presentation', 'Presentation', 'Slide decks and presentation materials.')
) as v(slug, name_en, description_en)
where services.slug = v.slug;

update academic_levels set translations = jsonb_build_object('en', jsonb_build_object('name', v.name_en))
from (values ('high-school', 'High School'), ('bachelor', 'Bachelor'), ('master', 'Master'), ('phd', 'PhD'))
  as v(slug, name_en)
where academic_levels.slug = v.slug;

update deadline_options set translations = jsonb_build_object('en', jsonb_build_object('label', v.label_en))
from (values (720, '30 days'), (336, '14 days'), (168, '7 days'), (72, '3 days'))
  as v(hours, label_en)
where deadline_options.duration_hours = v.hours;

update languages set translations = jsonb_build_object('en', jsonb_build_object('name', v.name_en))
from (values ('en', 'English'), ('az', 'Azerbaijani'), ('ru', 'Russian'))
  as v(code, name_en)
where languages.code = v.code;

update additional_services set translations = jsonb_build_object('en', jsonb_build_object('name', v.name_en, 'description', v.description_en))
from (values
  ('Plagiat Hesabatı', 'Plagiarism Report', 'Full similarity report included with delivery.'),
  ('Əvvəlcə Qaralama Planı', 'Draft Outline First', 'Receive an outline before full writing begins.'),
  ('Aparıcı Yazar', 'Top Writer', 'Assigned to a senior writer.'),
  ('Fərdi Məsləhət', 'One-on-One Consultation', '30-minute consultation call.')
) as v(name_az, name_en, description_en)
where additional_services.name = v.name_az;

-- FAQs and testimonials already carry a translations column (see
-- 20260101000002_core_tables.sql) — it was just never populated or read.
update faqs set translations = jsonb_build_object('en', jsonb_build_object(
  'question', v.question_en, 'answer', v.answer_en
))
from (values
  ('Sifarişimin vəziyyətini necə izləyə bilərəm?',
   'How can I track my order status?',
   'Once you place an order, you get a unique order number and a tracking link. If you are signed in, you can track all your orders in real time from the "My Orders" section.'),
  ('Plagiat yoxlanışı sifarişimə daxildirmi?',
   'Is a plagiarism check included in my order?',
   'Not by default, but you can add the "Plagiarism Check" add-on at checkout. It becomes free once your order reaches 500 AZN.'),
  ('Məlumatlarım məxfi qalacaqmı?',
   'Will my information stay confidential?',
   'Yes. Your order details and files are only visible to you and authorized staff.'),
  ('Çatdırılmadan sonra düzəliş tələb edə bilərəmmi?',
   'Can I request revisions after delivery?',
   'Yes, you can request revisions directly from your order page after delivery.'),
  ('Hesab yaratmadan (qonaq kimi) sifariş verə bilərəmmi?',
   'Can I order without creating an account?',
   'Yes. You can check out as a guest and track your order with your order number and tracking link. You can create an account later and link the order to it.'),
  ('Son tarixi seçdikdən sonra dəyişə bilərəmmi?',
   'Can I change the deadline after placing my order?',
   'Yes, you can contact us via the messages section to request a deadline change. Note that this may affect your order price.')
) as v(question_az, question_en, answer_en)
where faqs.question = v.question_az;

update testimonials set translations = jsonb_build_object('en', jsonb_build_object(
  'author_name', v.author_name_en, 'author_context', v.author_context_en, 'quote', v.quote_en
))
from (values
  ('A.M.', 'A.M.', 'Master''s student', 'Clear communication and delivered on time — I tracked the whole process from my order page.'),
  ('R.H.', 'R.H.', 'Bachelor''s student', 'The pricing calculator made it easy to see the cost upfront.'),
  ('S.K.', 'S.K.', 'PhD student', 'I received thorough, professional support on my dissertation chapter.'),
  ('N.Q.', 'N.Q.', 'Bachelor''s student', 'Delivered right on the deadline, and the messaging section made communication easy.')
) as v(author_name_az, author_name_en, author_context_en, quote_en)
where testimonials.author_name = v.author_name_az;

-- ---------- supabase/migrations/20260101000013_plagiarism_pricing.sql ----------
-- Narix Academy — dynamic Plagiarism Check pricing
--
-- Plagiarism Check is 1 AZN/page, free once the *service* subtotal (the
-- per-service progressive/per-page formula result — before language,
-- citation, or any other add-on) reaches 500 AZN. This can't be expressed
-- by the generic fixed/percentage additional_services model, so it's
-- special-cased in calculate_price() behind this flag column, keeping the
-- generic model untouched for every other add-on.

alter table additional_services add column if not exists is_plagiarism_addon boolean not null default false;

update additional_services
   set name = 'Plagiat Yoxlanışı',
       description = '1 AZN/səhifə. Sifariş 500 AZN və yuxarı olduqda pulsuzdur.',
       is_plagiarism_addon = true,
       translations = translations || jsonb_build_object(
         'en', jsonb_build_object(
           'name', 'Plagiarism Check',
           'description', '1 AZN per page — free for orders of 500 AZN or more.'
         )
       )
 where name = 'Plagiat Hesabatı';

-- ---------------------------------------------------------------------------
-- calculate_price() — addon pricing is now fully computed here (including
-- the plagiarism special case) and returned as `computed_price` per addon;
-- create_order() persists that value directly rather than re-deriving it,
-- so there is exactly one place addon prices are ever calculated.
-- ---------------------------------------------------------------------------

create or replace function calculate_price(
  p_service_id uuid,
  p_academic_level_id uuid,
  p_deadline_option_id uuid,
  p_word_count int,
  p_page_count numeric,
  p_language_id uuid,
  p_citation_style_id uuid,
  p_additional_service_ids uuid[],
  p_user_id uuid,
  p_promo_code text,
  p_referral_benefit_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rule service_pricing_rules;
  pages int;
  lang languages;
  citation citation_styles;
  addon additional_services;
  addon_id uuid;
  addon_price numeric(10,2);
  service_base numeric(10,2);
  base numeric(10,2);
  addons_total numeric(10,2) := 0;
  addons_breakdown jsonb := '[]'::jsonb;
  subtotal numeric(10,2);
  candidates jsonb := '[]'::jsonb;
  best jsonb := null;
  cand jsonb;
  member_pct numeric(5,2);
  early discounts;
  promo promo_codes;
  promo_discount discounts;
  benefit referral_benefits;
  is_verified boolean;
begin
  if not exists (select 1 from academic_levels where id = p_academic_level_id and is_active = true) then
    raise exception 'INVALID_ACADEMIC_LEVEL' using errcode = 'P0001';
  end if;
  if not exists (select 1 from deadline_options where id = p_deadline_option_id and is_active = true) then
    raise exception 'INVALID_DEADLINE' using errcode = 'P0001';
  end if;

  if p_page_count is null or p_page_count <> trunc(p_page_count) or p_page_count < 1 then
    raise exception 'INVALID_PAGE_COUNT' using errcode = 'P0001';
  end if;
  pages := p_page_count::int;

  select * into rule from service_pricing_rules where service_id = p_service_id;
  if rule is null then
    raise exception 'NO_PRICING_RULE' using errcode = 'P0001';
  end if;

  if rule.pricing_type = 'per_page' then
    if rule.minimum_pages is not null and pages < rule.minimum_pages then
      raise exception 'BELOW_MINIMUM_PAGES:%', rule.minimum_pages using errcode = 'P0001';
    end if;
    service_base := pages * rule.price_per_page;
  else
    if pages <= rule.base_pages then
      service_base := case when rule.base_mode = 'flat' then rule.base_price else pages * rule.base_price end;
    else
      service_base := (case when rule.base_mode = 'flat' then rule.base_price else rule.base_pages * rule.base_price end)
              + (pages - rule.base_pages) * rule.additional_page_price;
    end if;
  end if;

  base := service_base;

  if p_language_id is not null then
    select * into lang from languages where id = p_language_id and is_active = true;
    if lang is not null then base := base + lang.extra_fee; end if;
  end if;

  if p_citation_style_id is not null then
    select * into citation from citation_styles where id = p_citation_style_id and is_active = true;
    if citation is not null then base := base + citation.extra_fee; end if;
  end if;

  if p_additional_service_ids is not null then
    foreach addon_id in array p_additional_service_ids loop
      select * into addon from additional_services where id = addon_id and is_active = true;
      if addon is not null then
        if addon.is_plagiarism_addon then
          -- Threshold is checked against the pure service subtotal, before
          -- language/citation fees or any other add-on — never against the
          -- running total, and never after plagiarism itself is added.
          addon_price := case when service_base >= 500 then 0 else pages * 1 end;
        elsif addon.price_type = 'fixed' then
          addon_price := addon.price_value;
        else
          addon_price := round(base * addon.price_value / 100, 2);
        end if;

        addons_total := addons_total + addon_price;
        addons_breakdown := addons_breakdown || jsonb_build_object(
          'id', addon.id, 'name', addon.name, 'price_type', addon.price_type,
          'price_value', addon.price_value, 'computed_price', addon_price,
          'is_plagiarism_addon', addon.is_plagiarism_addon
        );
      end if;
    end loop;
  end if;

  subtotal := base + addons_total;

  if p_user_id is not null then
    select email_verified into is_verified from profiles where id = p_user_id;
    if is_verified then
      select percentage into member_pct from discounts
       where type = 'member' and active = true
       order by created_at desc limit 1;
      if member_pct is not null then
        candidates := candidates || jsonb_build_object(
          'source', 'member', 'reference_id', null,
          'percentage', member_pct, 'amount', round(subtotal * member_pct / 100, 2)
        );
      end if;
    end if;
  end if;

  select * into early from discounts
   where type = 'early_order' and active = true
     and (start_date is null or start_date <= now())
     and (end_date is null or end_date >= now())
   order by created_at desc limit 1;
  if early is not null and early.percentage is not null then
    candidates := candidates || jsonb_build_object(
      'source', 'early_order', 'reference_id', early.id,
      'percentage', early.percentage, 'amount', round(subtotal * early.percentage / 100, 2)
    );
  end if;

  if p_referral_benefit_id is not null then
    select * into benefit from referral_benefits
     where id = p_referral_benefit_id
       and beneficiary_user_id = p_user_id
       and status = 'approved'
       and consumed_at is null
       and (expires_at is null or expires_at > now());
    if benefit is not null then
      candidates := candidates || jsonb_build_object(
        'source', 'referral', 'reference_id', benefit.id,
        'percentage', benefit.percentage, 'amount', round(subtotal * benefit.percentage / 100, 2)
      );
    end if;
  end if;

  if p_promo_code is not null and length(trim(p_promo_code)) > 0 then
    select * into promo from promo_codes
     where code = upper(trim(p_promo_code))
       and active = true
       and current_uses < max_total_uses
       and (expires_at is null or expires_at > now());
    if promo is not null then
      select * into promo_discount from discounts where id = promo.discount_id and active = true;
      if promo_discount is not null and (promo_discount.minimum_order is null or subtotal >= promo_discount.minimum_order) then
        cand := jsonb_build_object('source', 'promo', 'reference_id', promo.id);
        if promo_discount.percentage is not null then
          cand := cand || jsonb_build_object(
            'percentage', promo_discount.percentage,
            'amount', round(subtotal * promo_discount.percentage / 100, 2)
          );
        else
          cand := cand || jsonb_build_object('percentage', 0, 'amount', least(promo_discount.fixed_amount, subtotal));
        end if;
        candidates := candidates || cand;
      end if;
    end if;
  end if;

  select c into best
    from (
      select c, (c->>'amount')::numeric as amt
      from jsonb_array_elements(candidates) c
      order by (c->>'amount')::numeric desc
      limit 1
    ) x;

  return jsonb_build_object(
    'base_price', base,
    'addons_total', addons_total,
    'addons_breakdown', addons_breakdown,
    'subtotal', subtotal,
    'candidates', candidates,
    'final_price', subtotal - coalesce((best->>'amount')::numeric, 0)
  ) || case when best is not null then jsonb_build_object('applied', best) else '{}'::jsonb end;
end;
$$;

-- ---------------------------------------------------------------------------
-- create_order() — persist the addon price calculate_price() already
-- computed, instead of re-deriving it from price_type/price_value (which
-- would silently ignore the plagiarism special case and double-maintain
-- the same math in two places).
-- ---------------------------------------------------------------------------

create or replace function create_order(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_guest_name text := p_payload->>'guest_name';
  v_guest_email text := p_payload->>'guest_email';
  v_guest_phone text := p_payload->>'guest_phone';
  v_service_id uuid := (p_payload->>'service_id')::uuid;
  v_academic_level_id uuid := (p_payload->>'academic_level_id')::uuid;
  v_deadline_option_id uuid := (p_payload->>'deadline_option_id')::uuid;
  v_word_count_option_id uuid := (p_payload->>'word_count_option_id')::uuid;
  v_word_count int := (p_payload->>'word_count')::int;
  v_page_count numeric := (p_payload->>'page_count')::numeric;
  v_language_id uuid := (p_payload->>'language_id')::uuid;
  v_citation_style_id uuid := (p_payload->>'citation_style_id')::uuid;
  v_addon_ids uuid[];
  v_subject text := p_payload->>'subject';
  v_topic text := p_payload->>'topic';
  v_description text := p_payload->>'description';
  v_university text := p_payload->>'university';
  v_college text := p_payload->>'college';
  v_promo_code text := p_payload->>'promo_code';
  v_referral_code text := p_payload->>'referral_code';

  v_pricing jsonb;
  v_existing_benefit_id uuid;
  v_order_id uuid;
  v_order_number text;
  v_status_id uuid;
  v_raw_token text;
  v_token_hash text;
  v_addon jsonb;
  v_cand jsonb;
  v_applied jsonb;
  v_referral_note text := null;
  admin_row record;
begin
  if v_user_id is null and (v_guest_email is null or length(trim(v_guest_email)) = 0) then
    raise exception 'GUEST_EMAIL_REQUIRED' using errcode = 'P0001';
  end if;

  select array_agg(value::uuid) into v_addon_ids
  from jsonb_array_elements_text(coalesce(p_payload->'additional_service_ids', '[]'::jsonb));

  if v_user_id is not null then
    select id into v_existing_benefit_id from referral_benefits
     where beneficiary_user_id = v_user_id and status = 'approved' and consumed_at is null
       and (expires_at is null or expires_at > now())
     order by created_at asc limit 1;
  end if;

  v_pricing := calculate_price(
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count, v_page_count,
    v_language_id, v_citation_style_id, v_addon_ids, v_user_id, v_promo_code, v_existing_benefit_id
  );

  v_applied := v_pricing->'applied';

  if v_applied is not null then
    if v_applied->>'source' = 'promo' then
      if not try_consume_promo_code((v_applied->>'reference_id')::uuid) then
        raise exception 'PROMO_CODE_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    elsif v_applied->>'source' = 'referral' then
      update referral_benefits
         set status = 'consumed', consumed_at = now()
       where id = (v_applied->>'reference_id')::uuid
         and status = 'approved' and consumed_at is null
      returning id into v_existing_benefit_id;
      if v_existing_benefit_id is null then
        raise exception 'REFERRAL_BENEFIT_NO_LONGER_AVAILABLE' using errcode = 'P0001';
      end if;
    end if;
  end if;

  select id into v_status_id from order_statuses where slug = 'new_order' and is_active = true;
  v_order_number := next_order_number();

  if v_user_id is null then
    v_raw_token := encode(gen_random_bytes(32), 'hex');
    v_token_hash := encode(digest(v_raw_token, 'sha256'), 'hex');
  end if;

  insert into orders (
    order_number, user_id, guest_name, guest_email, guest_phone, guest_token_hash,
    service_id, academic_level_id, deadline_option_id, word_count_option_id,
    word_count, page_count, language_id, citation_style_id,
    subject, topic, description, university, college,
    base_price, discount_source, discount_percentage, discount_amount, final_price,
    status_id
  ) values (
    v_order_number, v_user_id, v_guest_name, v_guest_email, v_guest_phone, v_token_hash,
    v_service_id, v_academic_level_id, v_deadline_option_id, v_word_count_option_id,
    v_word_count, v_page_count, v_language_id, v_citation_style_id,
    v_subject, v_topic, v_description, v_university, v_college,
    (v_pricing->>'base_price')::numeric,
    case when v_applied is not null then (v_applied->>'source')::discount_type else null end,
    coalesce((v_applied->>'percentage')::numeric, 0),
    coalesce((v_applied->>'amount')::numeric, 0),
    (v_pricing->>'final_price')::numeric,
    v_status_id
  ) returning id into v_order_id;

  insert into order_pricing_snapshots (order_id, snapshot, config_version)
  values (v_order_id, v_pricing, to_char(now(), 'YYYYMMDDHH24MISS'));

  for v_addon in select * from jsonb_array_elements(coalesce(v_pricing->'addons_breakdown', '[]'::jsonb)) loop
    insert into order_additional_services (order_id, additional_service_id, name_at_order, price_at_order)
    values (v_order_id, (v_addon->>'id')::uuid, v_addon->>'name', (v_addon->>'computed_price')::numeric);
  end loop;

  for v_cand in select * from jsonb_array_elements(coalesce(v_pricing->'candidates', '[]'::jsonb)) loop
    insert into discount_applications (order_id, discount_source, reference_id, percentage_considered, amount_considered, applied, reason)
    values (
      v_order_id, (v_cand->>'source')::discount_type, (v_cand->>'reference_id')::uuid,
      (v_cand->>'percentage')::numeric, (v_cand->>'amount')::numeric,
      v_applied is not null and v_cand = v_applied,
      case when v_applied is not null and v_cand = v_applied then 'highest value candidate'
           else 'lower value than applied ' || coalesce(v_applied->>'source', 'discount') end
    );
  end loop;

  insert into order_status_history (order_id, from_status_id, to_status_id, note)
  values (v_order_id, null, v_status_id, 'Order created');

  if v_referral_code is not null and length(trim(v_referral_code)) > 0 and v_user_id is not null then
    v_referral_note := redeem_referral_code(v_referral_code, v_user_id, v_order_id);
  end if;

  if v_user_id is not null then
    perform enqueue_notification(v_user_id, 'order_created', 'Order ' || v_order_number || ' received', 'We have received your order.', v_order_id);
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', v_user_id, profile_email(v_user_id), jsonb_build_object('order_number', v_order_number));
  else
    perform enqueue_email_job('order_created', 'order_created:' || v_order_id::text, 'order_created', null, v_guest_email, jsonb_build_object('order_number', v_order_number));
  end if;

  for admin_row in select id from profiles where role = 'admin' loop
    perform enqueue_notification(admin_row.id, 'new_order', 'New order ' || v_order_number, 'A new order was submitted.', v_order_id);
  end loop;

  return jsonb_build_object(
    'order_id', v_order_id,
    'order_number', v_order_number,
    'final_price', v_pricing->>'final_price',
    'guest_token', v_raw_token,
    'referral_status', v_referral_note
  );
end;
$$;

-- ---------- supabase/migrations/20260101000014_deadline_surcharge.sql ----------
-- Per-service deadline surcharge.
--
-- Dissertasiya/Buraxılış İşi get two extra long deadlines (90/60 gün) that no
-- other service offers, and every service now has a deadline-driven price
-- surcharge — but the two tables of percentages differ completely between
-- "long-form" services and everything else. Rather than branch on service
-- slug inside calculate_price(), the mapping (which deadlines a service may
-- use, its default, and its surcharge %) lives in a new join table —
-- service_deadline_options — so the pricing function stays generic and the
-- only place service names are special-cased is this one seed insert.

-- ---------------------------------------------------------------------------
-- Price increase: +2 AZN/page on both long-form services.
-- ---------------------------------------------------------------------------
update service_pricing_rules
set price_per_page = price_per_page + 2
where service_id in (
  select id from services where slug in ('dissertation', 'graduation-project')
);

-- ---------------------------------------------------------------------------
-- New deadline options: 90 gün (default for long-form) and 60 gün.
-- ---------------------------------------------------------------------------
insert into deadline_options (label, duration_hours, display_order, translations) values
  ('90 gün', 2160, 5, jsonb_build_object('en', jsonb_build_object('label', '90 days'))),
  ('60 gün', 1440, 8, jsonb_build_object('en', jsonb_build_object('label', '60 days')))
on conflict (label) do nothing;

-- ---------------------------------------------------------------------------
-- service_deadline_options: which deadlines a service offers, its default,
-- and the surcharge percentage applied to that service's subtotal.
-- ---------------------------------------------------------------------------
create table service_deadline_options (
  service_id uuid not null references services(id) on delete cascade,
  deadline_option_id uuid not null references deadline_options(id) on delete cascade,
  surcharge_percent numeric(5,2) not null default 0,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (service_id, deadline_option_id)
);

alter table service_deadline_options enable row level security;

create policy service_deadline_options_read on service_deadline_options for select using (true);
create policy service_deadline_options_write on service_deadline_options for all using (is_admin()) with check (is_admin());

create trigger set_updated_at before update on service_deadline_options
  for each row execute function set_updated_at();

-- Keys on (service_id, deadline_option_id), not id — same reason
-- service_pricing_rules and site_settings got their own audit trigger.
create or replace function log_service_deadline_options_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into audit_logs (actor_id, action, entity_type, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op),
    'service_deadline_options',
    coalesce(new.service_id::text, old.service_id::text) || ':' || coalesce(new.deadline_option_id::text, old.deadline_option_id::text),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('UPDATE','INSERT') then to_jsonb(new) else null end
  );
  return coalesce(new, old);
end;
$$;

create trigger audit_service_deadline_options after insert or update or delete on service_deadline_options
  for each row execute function log_service_deadline_options_change();

-- Long-form services: 90 gün default, 0/10/25/35/45/55% for 90/60/30/14/7/3.
insert into service_deadline_options (service_id, deadline_option_id, surcharge_percent, is_default)
select s.id, d.id, v.pct, v.is_default
from services s
join (values
  ('90 gün', 0::numeric, true),
  ('60 gün', 10::numeric, false),
  ('30 gün', 25::numeric, false),
  ('14 gün', 35::numeric, false),
  ('7 gün', 45::numeric, false),
  ('3 gün', 55::numeric, false)
) as v(label, pct, is_default) on true
join deadline_options d on d.label = v.label
where s.slug in ('dissertation', 'graduation-project')
on conflict (service_id, deadline_option_id) do update
  set surcharge_percent = excluded.surcharge_percent, is_default = excluded.is_default;

-- All other services: 30 gün default, 0/5/10/15% for 30/14/7/3.
insert into service_deadline_options (service_id, deadline_option_id, surcharge_percent, is_default)
select s.id, d.id, v.pct, v.is_default
from services s
join (values
  ('30 gün', 0::numeric, true),
  ('14 gün', 5::numeric, false),
  ('7 gün', 10::numeric, false),
  ('3 gün', 15::numeric, false)
) as v(label, pct, is_default) on true
join deadline_options d on d.label = v.label
where s.slug not in ('dissertation', 'graduation-project')
on conflict (service_id, deadline_option_id) do update
  set surcharge_percent = excluded.surcharge_percent, is_default = excluded.is_default;

-- ---------------------------------------------------------------------------
-- calculate_price(): validate the (service, deadline) pair against
-- service_deadline_options and apply its surcharge_percent to the subtotal
-- (service price + language/citation fees + add-ons, plagiarism included)
-- BEFORE discount candidates are evaluated — so member/early-order/referral/
-- promo discounts are computed on the deadline-inflated amount, matching
-- every other discount already being computed on the full pre-discount
-- subtotal. The plagiarism free-at-500 threshold still checks service_base
-- alone, unaffected by the deadline surcharge (unchanged from before).
-- ---------------------------------------------------------------------------
create or replace function calculate_price(
  p_service_id uuid,
  p_academic_level_id uuid,
  p_deadline_option_id uuid,
  p_word_count int,
  p_page_count numeric,
  p_language_id uuid,
  p_citation_style_id uuid,
  p_additional_service_ids uuid[],
  p_user_id uuid,
  p_promo_code text,
  p_referral_benefit_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  rule service_pricing_rules;
  pages int;
  lang languages;
  citation citation_styles;
  addon additional_services;
  addon_id uuid;
  addon_price numeric(10,2);
  service_base numeric(10,2);
  base numeric(10,2);
  addons_total numeric(10,2) := 0;
  addons_breakdown jsonb := '[]'::jsonb;
  deadline_surcharge_percent numeric(5,2);
  deadline_surcharge_amount numeric(10,2);
  subtotal numeric(10,2);
  candidates jsonb := '[]'::jsonb;
  best jsonb := null;
  cand jsonb;
  member_pct numeric(5,2);
  early discounts;
  promo promo_codes;
  promo_discount discounts;
  benefit referral_benefits;
  is_verified boolean;
begin
  if not exists (select 1 from academic_levels where id = p_academic_level_id and is_active = true) then
    raise exception 'INVALID_ACADEMIC_LEVEL' using errcode = 'P0001';
  end if;
  if not exists (select 1 from deadline_options where id = p_deadline_option_id and is_active = true) then
    raise exception 'INVALID_DEADLINE' using errcode = 'P0001';
  end if;

  select surcharge_percent into deadline_surcharge_percent
    from service_deadline_options
   where service_id = p_service_id and deadline_option_id = p_deadline_option_id;
  if deadline_surcharge_percent is null then
    raise exception 'INVALID_DEADLINE_FOR_SERVICE' using errcode = 'P0001';
  end if;

  if p_page_count is null or p_page_count <> trunc(p_page_count) or p_page_count < 1 then
    raise exception 'INVALID_PAGE_COUNT' using errcode = 'P0001';
  end if;
  pages := p_page_count::int;

  select * into rule from service_pricing_rules where service_id = p_service_id;
  if rule is null then
    raise exception 'NO_PRICING_RULE' using errcode = 'P0001';
  end if;

  if rule.pricing_type = 'per_page' then
    if rule.minimum_pages is not null and pages < rule.minimum_pages then
      raise exception 'BELOW_MINIMUM_PAGES:%', rule.minimum_pages using errcode = 'P0001';
    end if;
    service_base := pages * rule.price_per_page;
  else
    if pages <= rule.base_pages then
      service_base := case when rule.base_mode = 'flat' then rule.base_price else pages * rule.base_price end;
    else
      service_base := (case when rule.base_mode = 'flat' then rule.base_price else rule.base_pages * rule.base_price end)
              + (pages - rule.base_pages) * rule.additional_page_price;
    end if;
  end if;

  base := service_base;

  if p_language_id is not null then
    select * into lang from languages where id = p_language_id and is_active = true;
    if lang is not null then base := base + lang.extra_fee; end if;
  end if;

  if p_citation_style_id is not null then
    select * into citation from citation_styles where id = p_citation_style_id and is_active = true;
    if citation is not null then base := base + citation.extra_fee; end if;
  end if;

  if p_additional_service_ids is not null then
    foreach addon_id in array p_additional_service_ids loop
      select * into addon from additional_services where id = addon_id and is_active = true;
      if addon is not null then
        if addon.is_plagiarism_addon then
          -- Threshold is checked against the pure service subtotal, before
          -- language/citation fees, other add-ons, or the deadline surcharge
          -- — never against the running total.
          addon_price := case when service_base >= 500 then 0 else pages * 1 end;
        elsif addon.price_type = 'fixed' then
          addon_price := addon.price_value;
        else
          addon_price := round(base * addon.price_value / 100, 2);
        end if;

        addons_total := addons_total + addon_price;
        addons_breakdown := addons_breakdown || jsonb_build_object(
          'id', addon.id, 'name', addon.name, 'price_type', addon.price_type,
          'price_value', addon.price_value, 'computed_price', addon_price,
          'is_plagiarism_addon', addon.is_plagiarism_addon
        );
      end if;
    end loop;
  end if;

  deadline_surcharge_amount := round((base + addons_total) * deadline_surcharge_percent / 100, 2);
  subtotal := base + addons_total + deadline_surcharge_amount;

  if p_user_id is not null then
    select email_verified into is_verified from profiles where id = p_user_id;
    if is_verified then
      select percentage into member_pct from discounts
       where type = 'member' and active = true
       order by created_at desc limit 1;
      if member_pct is not null then
        candidates := candidates || jsonb_build_object(
          'source', 'member', 'reference_id', null,
          'percentage', member_pct, 'amount', round(subtotal * member_pct / 100, 2)
        );
      end if;
    end if;
  end if;

  select * into early from discounts
   where type = 'early_order' and active = true
     and (start_date is null or start_date <= now())
     and (end_date is null or end_date >= now())
   order by created_at desc limit 1;
  if early is not null and early.percentage is not null then
    candidates := candidates || jsonb_build_object(
      'source', 'early_order', 'reference_id', early.id,
      'percentage', early.percentage, 'amount', round(subtotal * early.percentage / 100, 2)
    );
  end if;

  if p_referral_benefit_id is not null then
    select * into benefit from referral_benefits
     where id = p_referral_benefit_id
       and beneficiary_user_id = p_user_id
       and status = 'approved'
       and consumed_at is null
       and (expires_at is null or expires_at > now());
    if benefit is not null then
      candidates := candidates || jsonb_build_object(
        'source', 'referral', 'reference_id', benefit.id,
        'percentage', benefit.percentage, 'amount', round(subtotal * benefit.percentage / 100, 2)
      );
    end if;
  end if;

  if p_promo_code is not null and length(trim(p_promo_code)) > 0 then
    select * into promo from promo_codes
     where code = upper(trim(p_promo_code))
       and active = true
       and current_uses < max_total_uses
       and (expires_at is null or expires_at > now());
    if promo is not null then
      select * into promo_discount from discounts where id = promo.discount_id and active = true;
      if promo_discount is not null and (promo_discount.minimum_order is null or subtotal >= promo_discount.minimum_order) then
        cand := jsonb_build_object('source', 'promo', 'reference_id', promo.id);
        if promo_discount.percentage is not null then
          cand := cand || jsonb_build_object(
            'percentage', promo_discount.percentage,
            'amount', round(subtotal * promo_discount.percentage / 100, 2)
          );
        else
          cand := cand || jsonb_build_object('percentage', 0, 'amount', least(promo_discount.fixed_amount, subtotal));
        end if;
        candidates := candidates || cand;
      end if;
    end if;
  end if;

  select c into best
    from (
      select c, (c->>'amount')::numeric as amt
      from jsonb_array_elements(candidates) c
      order by (c->>'amount')::numeric desc
      limit 1
    ) x;

  return jsonb_build_object(
    'base_price', base,
    'addons_total', addons_total,
    'addons_breakdown', addons_breakdown,
    'deadline_surcharge_percent', deadline_surcharge_percent,
    'deadline_surcharge_amount', deadline_surcharge_amount,
    'subtotal', subtotal,
    'candidates', candidates,
    'final_price', subtotal - coalesce((best->>'amount')::numeric, 0)
  ) || case when best is not null then jsonb_build_object('applied', best) else '{}'::jsonb end;
end;
$$;

-- ---------- supabase/migrations/20260101000015_pgcrypto_search_path.sql ----------
-- Guest checkout was failing end-to-end: create_order(), get_order_by_token(),
-- and claim_guest_order() all use pgcrypto's gen_random_bytes()/digest() to
-- generate and hash the guest tracking token, but each is SECURITY DEFINER
-- with `set search_path = public` only. On Supabase Cloud, pgcrypto lives in
-- the `extensions` schema (the `create extension if not exists pgcrypto`
-- in the first migration was a no-op there, since it's pre-installed), so
-- these functions couldn't resolve gen_random_bytes/digest at all — every
-- guest order submission errored, and any already-placed guest order was
-- unreachable via its tracking link. Logged-in orders were unaffected,
-- since the guest-token branch only runs when there's no auth.uid().
alter function create_order(jsonb) set search_path = public, extensions;
alter function get_order_by_token(text) set search_path = public, extensions;
alter function claim_guest_order(text, text) set search_path = public, extensions;

-- ---------- supabase/migrations/20260101000016_messages_realtime.sql ----------
-- MessageThread subscribes to postgres_changes on `messages`, but the table
-- was never added to the supabase_realtime publication — so every message
-- was actually inserted successfully, it just never appeared anywhere,
-- neither for the sender (no optimistic update in the client either — see
-- the accompanying MessageThread fix) nor for the other side (no realtime
-- push). `if not exists` guards against re-running this against a project
-- where it was already added by hand.
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages'
  ) then
    alter publication supabase_realtime add table messages;
  end if;
end $$;

